const apply = () => { document.querySelectorAll('label[for="postcode"], label[for="distance"], label[for="min-price"], label[for="max-price"], label[for="sort"]').forEach((l) => {
  const s = document.createElement('span');
  s.className = 'dj-label';
  s.innerHTML = l.innerHTML;
  l.replaceWith(s);
}); };
const mo = new MutationObserver(() => { mo.disconnect(); apply(); mo.observe(document.body, { childList: true, subtree: true }); });
apply();
mo.observe(document.body, { childList: true, subtree: true });
